#!/usr/bin/env python3
# Answer-agnostic full (op,opnd) disassembly of session.bin. 2-byte aligned (verified: all
# 0x80ff print-markers at even offsets). Groups 0x81-char runs as EMIT strings.
import sys, collections
fw=open(sys.argv[1],'rb').read()
N=len(fw)
freq=collections.Counter()
for i in range(0,N-1,2):
    freq[fw[i]]+=1

lines=[]
i=0
run=[]; runstart=None
def flush():
    global run,runstart
    if run:
        s=''.join(run)
        lines.append(f"{runstart:04d}: EMIT '{s}'")
        run=[]; runstart=None
while i+1<N:
    op=fw[i]; opnd=fw[i+1]
    if op==0x81:
        if runstart is None: runstart=i
        run.append(chr(opnd) if 32<=opnd<127 else ('\\n' if opnd==0x0a else f'<{opnd:02x}>'))
    else:
        flush()
        lines.append(f"{i:04d}: {op:02x} {opnd:02x}   op={op:3d} opnd={opnd:3d}")
    i+=2
flush()

mode=sys.argv[2] if len(sys.argv)>2 else 'all'
if mode=='freq':
    print("opcode frequency (op: count):")
    for op,c in freq.most_common():
        print(f"  0x{op:02x} ({op:3d}): {c}")
elif mode.startswith('range:'):
    a,b=mode[6:].split('-'); a=int(a); b=int(b)
    for l in lines:
        off=int(l[:4])
        if a<=off<=b: print(l)
else:
    for l in lines: print(l)

